<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'; import { computed } from 'vue'; import InputError from '@/components/InputError.vue'; import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type Presentation = { id: string; name: string; sku: string; unit: string; physical_quantity: string; average_unit_cost: number; allow_negative_stock: boolean };
const props = defineProps<{ presentations: Presentation[] }>(); const now = new Date(); const localNow = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16); const form = useForm({ adjustment_type: 'manual', effective_at: localNow, reason: '', lines: [] as { presentation_id: string; counted_quantity: string; unit_cost: number | null }[] }); const available = computed(() => props.presentations.filter((presentation) => !form.lines.some((line) => line.presentation_id === presentation.id))); const selected = (id: string) => props.presentations.find((presentation) => presentation.id === id); const add = () => { const presentation = available.value[0]; if (presentation) form.lines.push({ presentation_id: presentation.id, counted_quantity: presentation.physical_quantity, unit_cost: presentation.average_unit_cost || null }); }; const remove = (index: number) => form.lines.splice(index, 1); const submit = () => form.post('/inventory/adjustments');
</script>
<template><Head title="Nuevo ajuste" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header><h1 class="text-2xl font-semibold">Nuevo ajuste de inventario</h1><p class="text-sm text-muted-foreground">Registra el conteo; el movimiento se genera únicamente al confirmar.</p></header><form class="max-w-4xl space-y-5" @submit.prevent="submit"><section class="grid gap-5 rounded-xl border bg-card p-5 md:grid-cols-2"><div class="grid gap-2"><Label>Tipo</Label><select v-model="form.adjustment_type" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="manual">Ajuste manual</option><option value="initial">Inventario inicial</option></select></div><div class="grid gap-2"><Label>Fecha efectiva</Label><Input v-model="form.effective_at" type="datetime-local" required /></div><div class="grid gap-2 md:col-span-2"><Label>Motivo</Label><textarea v-model="form.reason" rows="3" required class="rounded-md border bg-transparent px-3 py-2 text-sm" /><InputError :message="form.errors.reason" /></div></section><section class="rounded-xl border bg-card p-5"><div class="mb-4 flex items-center justify-between"><div><h2 class="font-semibold">Conteo</h2><p class="text-sm text-muted-foreground">El costo se usa únicamente cuando el conteo genera una entrada.</p></div><Button type="button" variant="outline" size="sm" :disabled="available.length === 0" @click="add">Agregar presentación</Button></div><div class="space-y-3"><div v-for="(line, index) in form.lines" :key="index" class="grid gap-2 rounded-lg border p-3 md:grid-cols-[1fr_9rem_10rem_auto]"><select v-model="line.presentation_id" required class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="presentation in presentations" :key="presentation.id" :value="presentation.id">{{ presentation.name }} ({{ presentation.sku }})</option></select><Input v-model="line.counted_quantity" type="number" step="any" required :title="`Existencia actual: ${selected(line.presentation_id)?.physical_quantity}`" /><Input v-model.number="line.unit_cost" type="number" min="0" step="1" placeholder="Costo COP" /><Button type="button" variant="ghost" @click="remove(index)">Quitar</Button><p class="text-xs text-muted-foreground md:col-span-4">Actual: {{ selected(line.presentation_id)?.physical_quantity }} {{ selected(line.presentation_id)?.unit }}<span v-if="selected(line.presentation_id)?.allow_negative_stock"> · admite autorización negativa</span></p></div><p v-if="form.lines.length === 0" class="py-6 text-center text-sm text-muted-foreground">Agrega las presentaciones contadas.</p></div><InputError :message="form.errors.lines" /></section><div class="flex justify-end gap-2"><Button type="button" variant="outline" as-child><a href="/inventory/adjustments">Cancelar</a></Button><Button type="submit" :disabled="form.processing || form.lines.length === 0">Guardar borrador</Button></div></form></main></template>
